def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    endpoints = []
    gates = []
    for r in range(h):
        c = 0
        while c < w:
            v = grid[r][c]
            if v not in (5, 7, 4):
                endpoints.append((r, c))
                c += 1
            elif v == 4:
                start = c
                while c < w and grid[r][c] == 4:
                    c += 1
                gates.append((r, (start + c - 1) // 2))
            else:
                c += 1

    endpoints.sort()
    gates.sort()
    color = grid[endpoints[0][0]][endpoints[0][1]]

    def vertical(c, r1, r2):
        for r in range(min(r1, r2), max(r1, r2) + 1):
            if out[r][c] != 7:
                out[r][c] = color

    def horizontal(r, c1, c2):
        for c in range(min(c1, c2), max(c1, c2) + 1):
            if out[r][c] != 7:
                out[r][c] = color

    r, c = endpoints[0]
    for gr, gc in gates:
        vertical(c, r, gr - 1)
        horizontal(gr - 1, c, gc)
        out[gr][gc] = color
        r, c = gr + 1, gc

    er, ec = endpoints[-1]
    vertical(c, r, er)
    horizontal(er, c, ec)
    return out
